import { useState, useEffect } from 'react';
import { Bell, X, Check, Trash2, MessageSquare, Award, AlertCircle, UserPlus, Calendar, ChevronRight } from 'lucide-react';
import { cn } from '@shared/lib/utils';
import { Card, CardContent } from '@frontend/components/ui/Card';
import Button from '@frontend/components/ui/Button';

const MOCK_NOTIFICATIONS = [
  { id: 1, type: 'message', title: 'New message from Sarah', description: 'Hey! I wanted to discuss the project timeline...', time: '2m ago', read: false },
  { id: 2, type: 'achievement', title: 'Achievement Unlocked!', description: 'You earned the "Community Builder" badge', time: '15m ago', read: false },
  { id: 3, type: 'alert', title: 'System Maintenance', description: 'Scheduled maintenance in 2 hours', time: '1h ago', read: false },
  { id: 4, type: 'mention', title: 'You were mentioned', description: 'Marcus mentioned you in a comment', time: '2h ago', read: true },
  { id: 5, type: 'invite', title: 'Team Invitation', description: 'You were invited to join "AI Research Team"', time: '3h ago', read: true },
  { id: 6, type: 'event', title: 'Upcoming Event', description: 'Community meetup tomorrow at 3 PM', time: '5h ago', read: true },
  { id: 7, type: 'message', title: 'New message from David', description: 'Thanks for the feedback on my PR', time: '1d ago', read: true },
];

export default function NotificationCenter() {
  const [isOpen, setIsOpen] = useState(false);
  const [notifications, setNotifications] = useState(MOCK_NOTIFICATIONS);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    setUnreadCount(notifications.filter(n => !n.read).length);
  }, [notifications]);

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'message': return MessageSquare;
      case 'achievement': return Award;
      case 'alert': return AlertCircle;
      case 'mention': return MessageSquare;
      case 'invite': return UserPlus;
      case 'event': return Calendar;
      default: return Bell;
    }
  };

  const getNotificationColor = (type) => {
    switch (type) {
      case 'message': return 'text-blue-400 bg-blue-500/10';
      case 'achievement': return 'text-yellow-400 bg-yellow-500/10';
      case 'alert': return 'text-red-400 bg-red-500/10';
      case 'mention': return 'text-purple-400 bg-purple-500/10';
      case 'invite': return 'text-emerald-400 bg-emerald-500/10';
      case 'event': return 'text-orange-400 bg-orange-500/10';
      default: return 'text-text-muted bg-white/5';
    }
  };

  const markAsRead = (id) => {
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, read: true })));
  };

  const deleteNotification = (id) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const clearAll = () => {
    setNotifications([]);
  };

  return (
    <>
      {/* Notification Bell Button */}
      <div className="relative">
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="relative p-2 rounded-xl bg-white/5 hover:bg-white/10 transition-colors"
        >
          <Bell className="h-5 w-5 text-text-muted hover:text-white" />
          {unreadCount > 0 && (
            <span className="absolute -top-1 -right-1 h-5 w-5 bg-accent text-white text-xs font-bold rounded-full flex items-center justify-center">
              {unreadCount > 9 ? '9+' : unreadCount}
            </span>
          )}
        </button>
      </div>

      {/* Floating Drawer */}
      {isOpen && (
        <>
          <div 
            className="fixed inset-0 bg-black/50 backdrop-blur-sm z-40"
            onClick={() => setIsOpen(false)}
          />
          <div className="fixed top-0 right-0 h-full w-full max-w-md bg-background border-l border-border z-50 shadow-2xl">
            <div className="flex flex-col h-full">
              {/* Header */}
              <div className="flex items-center justify-between p-4 border-b border-border">
                <div className="flex items-center gap-3">
                  <Bell className="h-5 w-5 text-accent" />
                  <h2 className="text-lg font-bold text-white">Notifications</h2>
                  {unreadCount > 0 && (
                    <span className="px-2 py-0.5 text-xs font-bold bg-accent text-white rounded-full">
                      {unreadCount} new
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  {unreadCount > 0 && (
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={markAllAsRead}
                      className="text-xs"
                    >
                      Mark all read
                    </Button>
                  )}
                  <button
                    onClick={() => setIsOpen(false)}
                    className="p-2 hover:bg-white/5 rounded-lg transition-colors"
                  >
                    <X className="h-5 w-5 text-text-muted" />
                  </button>
                </div>
              </div>

              {/* Notifications List */}
              <div className="flex-1 overflow-y-auto">
                {notifications.length === 0 ? (
                  <div className="flex flex-col items-center justify-center h-full p-8 text-center">
                    <Bell className="h-12 w-12 text-text-muted mb-4" />
                    <p className="text-text-muted">No notifications</p>
                  </div>
                ) : (
                  <div className="divide-y divide-border">
                    {notifications.map((notification) => {
                      const Icon = getNotificationIcon(notification.type);
                      return (
                        <div
                          key={notification.id}
                          className={cn(
                            "p-4 hover:bg-white/[0.02] transition-colors cursor-pointer",
                            !notification.read && "bg-white/[0.03]"
                          )}
                        >
                          <div className="flex items-start gap-3">
                            <div className={cn("p-2 rounded-lg shrink-0", getNotificationColor(notification.type))}>
                              <Icon className="h-4 w-4" />
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="flex items-start justify-between gap-2 mb-1">
                                <h3 className={cn("font-medium text-white text-sm", !notification.read && "font-bold")}>
                                  {notification.title}
                                </h3>
                                {!notification.read && (
                                  <button
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      markAsRead(notification.id);
                                    }}
                                    className="p-1 hover:bg-white/10 rounded transition-colors"
                                  >
                                    <Check className="h-3 w-3 text-text-muted" />
                                  </button>
                                )}
                              </div>
                              <p className="text-sm text-text-muted mb-2 line-clamp-2">
                                {notification.description}
                              </p>
                              <div className="flex items-center justify-between">
                                <span className="text-xs text-text-muted">{notification.time}</span>
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    deleteNotification(notification.id);
                                  }}
                                  className="p-1 hover:bg-white/10 rounded transition-colors"
                                >
                                  <Trash2 className="h-3 w-3 text-text-muted" />
                                </button>
                              </div>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* Footer */}
              {notifications.length > 0 && (
                <div className="p-4 border-t border-border">
                  <Button
                    variant="ghost"
                    onClick={clearAll}
                    className="w-full text-text-muted hover:text-white"
                  >
                    <Trash2 className="h-4 w-4 mr-2" />
                    Clear all notifications
                  </Button>
                </div>
              )}
            </div>
          </div>
        </>
      )}
    </>
  );
}

// Export a hook for using the notification center in other components
export function useNotificationCount() {
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    setUnreadCount(MOCK_NOTIFICATIONS.filter(n => !n.read).length);
  }, []);

  return unreadCount;
}

import { useState } from 'react';
import { Bot, Sparkles, FileText, Copy, Check } from 'lucide-react';
import Button from '@frontend/components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '@frontend/components/ui/Card';

export function AIResearchAssistant({ paperText, onCitationGenerated }) {
  const [query, setQuery] = useState('');
  const [response, setResponse] = useState('');
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleQuery = async () => {
    if (!query.trim()) return;
    setLoading(true);

    // Simulate AI response - in production, call AI API
    setTimeout(() => {
      const responses = {
        summary: `Based on the paper, here's a summary:\n\n${paperText.substring(0, 200)}...`,
        citation: `APA Citation: Author, A. A. (Year). Title. Journal Name, Volume(Issue), pages.\n\nMLA Citation: Author. "Title." Journal Name, vol. X, no. Y, Year, pp. pages.\n\nChicago Citation: Author. "Title." Journal Name Volume, no. Issue (Year): pages.`,
        analysis: `The paper presents significant findings in the field. Key contributions include:\n\n1. Novel methodology\n2. Comprehensive data analysis\n3. Practical applications`,
      };

      const selectedResponse = responses[query.toLowerCase().includes('citation') ? 'citation' : query.toLowerCase().includes('summary') ? 'summary' : 'analysis'];
      setResponse(selectedResponse);
      setLoading(false);
    }, 1500);
  };

  const handleCitationFormat = (format) => {
    const citations = {
      apa: `${paperText.split(' ')[0] || 'Author'} (${new Date().getFullYear()}). Title. Journal, 1(1), 1-10.`,
      mla: `${paperText.split(' ')[0] || 'Author'}. "Title." Journal, vol. 1, no. 1, ${new Date().getFullYear()}, pp. 1-10.`,
      chicago: `${paperText.split(' ')[0] || 'Author'}. "Title." Journal 1, no. 1 (${new Date().getFullYear()}): 1-10.`,
    };
    setResponse(citations[format]);
    if (onCitationGenerated) onCitationGenerated(citations[format]);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(response);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Card className="h-full">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Bot className="h-5 w-5 text-accent" />
          AI Research Assistant
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Quick Actions */}
        <div className="space-y-2">
          <p className="text-xs font-bold text-text-muted uppercase tracking-widest">Quick Actions</p>
          <div className="flex flex-wrap gap-2">
            <Button size="sm" variant="secondary" onClick={() => handleCitationFormat('apa')}>
              APA Citation
            </Button>
            <Button size="sm" variant="secondary" onClick={() => handleCitationFormat('mla')}>
              MLA Citation
            </Button>
            <Button size="sm" variant="secondary" onClick={() => handleCitationFormat('chicago')}>
              Chicago Citation
            </Button>
            <Button size="sm" variant="secondary" onClick={() => { setQuery('Generate summary'); handleQuery(); }}>
              <Sparkles className="mr-1 h-3 w-3" />
              Summarize
            </Button>
          </div>
        </div>

        {/* Query Input */}
        <div className="space-y-2">
          <p className="text-xs font-bold text-text-muted uppercase tracking-widest">Ask AI</p>
          <div className="flex gap-2">
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Ask about the paper..."
              className="flex-1 rounded-lg border border-border bg-black/30 px-3 py-2 text-sm text-white outline-none focus:border-accent"
              onKeyPress={(e) => e.key === 'Enter' && handleQuery()}
            />
            <Button size="sm" onClick={handleQuery} disabled={loading}>
              {loading ? '...' : 'Ask'}
            </Button>
          </div>
        </div>

        {/* Response */}
        {response && (
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <p className="text-xs font-bold text-text-muted uppercase tracking-widest">Response</p>
              <button
                onClick={copyToClipboard}
                className="flex items-center gap-1 text-xs text-text-muted hover:text-white"
              >
                {copied ? <Check className="h-3 w-3" /> : <Copy className="h-3 w-3" />}
                {copied ? 'Copied' : 'Copy'}
              </button>
            </div>
            <div className="rounded-lg border border-border bg-white/[0.03] p-3">
              <pre className="whitespace-pre-wrap text-sm text-text-soft font-sans">{response}</pre>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from 'react';
import { MessageSquare, Send, Reply, ThumbsUp, CheckCircle2 } from 'lucide-react';
import Button from '@frontend/components/ui/Button';
import { Input } from '@frontend/components/ui/Input';
import { Card, CardContent, CardHeader, CardTitle } from '@frontend/components/ui/Card';
import { useAuth } from '@frontend/features/auth/AuthContext';

export function PeerReviewPanel({ paperId, paperTitle }) {
  const { user } = useAuth();
  const [comments, setComments] = useState([
    {
      id: '1',
      author: 'Dr. Sarah Chen',
      text: 'The methodology section is well-structured. However, I suggest adding more statistical analysis to support your conclusions.',
      timestamp: new Date(Date.now() - 86400000),
      replies: [
        {
          id: '1-1',
          author: 'Author',
          text: 'Thank you for the feedback! We will include additional statistical analysis in the revision.',
          timestamp: new Date(Date.now() - 43200000),
        },
      ],
      upvotes: 3,
      isHelpful: false,
    },
    {
      id: '2',
      author: 'Prof. Michael Roberts',
      text: 'Excellent work on the literature review. The citations are comprehensive and relevant.',
      timestamp: new Date(Date.now() - 172800000),
      replies: [],
      upvotes: 5,
      isHelpful: true,
    },
  ]);
  const [newComment, setNewComment] = useState('');
  const [replyingTo, setReplyingTo] = useState(null);
  const [replyText, setReplyText] = useState('');

  const handleSubmitComment = () => {
    if (!newComment.trim()) return;

    const comment = {
      id: Date.now().toString(),
      author: user?.displayName || 'Anonymous',
      text: newComment,
      timestamp: new Date(),
      replies: [],
      upvotes: 0,
      isHelpful: false,
    };

    setComments(prev => [comment, ...prev]);
    setNewComment('');
  };

  const handleSubmitReply = (commentId) => {
    if (!replyText.trim()) return;

    const reply = {
      id: `${commentId}-${Date.now()}`,
      author: user?.displayName || 'Anonymous',
      text: replyText,
      timestamp: new Date(),
    };

    setComments(prev => prev.map(comment => {
      if (comment.id === commentId) {
        return {
          ...comment,
          replies: [...comment.replies, reply],
        };
      }
      return comment;
    }));

    setReplyText('');
    setReplyingTo(null);
  };

  const handleUpvote = (commentId) => {
    setComments(prev => prev.map(comment => {
      if (comment.id === commentId) {
        return {
          ...comment,
          upvotes: comment.upvotes + 1,
        };
      }
      return comment;
    }));
  };

  const markHelpful = (commentId) => {
    setComments(prev => prev.map(comment => {
      if (comment.id === commentId) {
        return {
          ...comment,
          isHelpful: !comment.isHelpful,
        };
      }
      return comment;
    }));
  };

  const formatDate = (date) => {
    const now = new Date();
    const diff = now - date;
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (days > 0) return `${days}d ago`;
    if (hours > 0) return `${hours}h ago`;
    return 'Just now';
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <MessageSquare className="h-5 w-5 text-accent" />
          Peer Review Discussion
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* New Comment */}
        <div className="space-y-2">
          <p className="text-xs font-bold text-text-muted uppercase tracking-widest">Add Your Review</p>
          <div className="flex gap-2">
            <Input
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              placeholder="Share your feedback on this research paper..."
              className="flex-1"
            />
            <Button size="sm" onClick={handleSubmitComment} disabled={!newComment.trim()}>
              <Send className="h-4 w-4" />
            </Button>
          </div>
        </div>

        {/* Comments List */}
        <div className="space-y-4">
          {comments.map(comment => (
            <div key={comment.id} className="space-y-3">
              <div className={`p-4 rounded-xl border ${comment.isHelpful ? 'border-green-500/40 bg-green-500/10' : 'border-border bg-white/[0.03]'}`}>
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-bold text-white">{comment.author}</span>
                      {comment.isHelpful && (
                        <span className="flex items-center gap-1 text-xs text-green-400">
                          <CheckCircle2 className="h-3 w-3" />
                          Helpful
                        </span>
                      )}
                    </div>
                    <span className="text-xs text-text-muted">{formatDate(comment.timestamp)}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => handleUpvote(comment.id)}
                      className="flex items-center gap-1 text-xs text-text-muted hover:text-accent"
                    >
                      <ThumbsUp className="h-3 w-3" />
                      {comment.upvotes}
                    </button>
                    <button
                      onClick={() => markHelpful(comment.id)}
                      className="text-xs text-text-muted hover:text-green-400"
                    >
                      {comment.isHelpful ? 'Unmark' : 'Mark Helpful'}
                    </button>
                  </div>
                </div>
                <p className="text-sm text-text-soft">{comment.text}</p>
                <button
                  onClick={() => setReplyingTo(comment.id)}
                  className="mt-2 flex items-center gap-1 text-xs font-bold text-accent hover:underline"
                >
                  <Reply className="h-3 w-3" />
                  Reply
                </button>
              </div>

              {/* Replies */}
              {comment.replies.length > 0 && (
                <div className="ml-8 space-y-2">
                  {comment.replies.map(reply => (
                    <div key={reply.id} className="p-3 rounded-lg border border-border bg-black/20">
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-sm font-bold text-white">{reply.author}</span>
                        <span className="text-xs text-text-muted">{formatDate(reply.timestamp)}</span>
                      </div>
                      <p className="text-sm text-text-soft">{reply.text}</p>
                    </div>
                  ))}
                </div>
              )}

              {/* Reply Input */}
              {replyingTo === comment.id && (
                <div className="ml-8 flex gap-2">
                  <Input
                    value={replyText}
                    onChange={(e) => setReplyText(e.target.value)}
                    placeholder="Write a reply..."
                    className="flex-1"
                  />
                  <Button size="sm" onClick={() => handleSubmitReply(comment.id)} disabled={!replyText.trim()}>
                    <Send className="h-4 w-4" />
                  </Button>
                  <Button size="sm" variant="ghost" onClick={() => { setReplyingTo(null); setReplyText(''); }}>
                    Cancel
                  </Button>
                </div>
              )}
            </div>
          ))}
        </div>

        {comments.length === 0 && (
          <div className="text-center py-8 text-text-muted">
            <MessageSquare className="mx-auto h-12 w-12 mb-4 opacity-50" />
            <p>No peer reviews yet. Be the first to provide feedback!</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useEffect, useState } from 'react';
import {
  Activity,
  Bot,
  CheckSquare,
  ClipboardList,
  FlaskConical,
  FolderKanban,
  Package,
  RefreshCw,
  Users,
  Wifi,
  Shield,
  Lock,
  Unlock,
  AlertTriangle } from 'lucide-react';
import { AdminService } from '@services/firestore/admin';
import { AdminMetric, AdminPanel, StatusBadge, LoadingRows } from './adminUtils';
import { formatDistanceToNow } from '@shared/lib/dateUtils';
import { Card, CardContent, CardHeader, CardTitle } from '@frontend/components/ui/Card';
import Button from '@frontend/components/ui/Button';

export default function AdminDashboard() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [platformLocked, setPlatformLocked] = useState(false);
  const [lockReason, setLockReason] = useState('');

  const load = async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    try {
      const result = await AdminService.getDashboardData();
      setData(result);
    } catch (err) {
      console.error('Admin dashboard failed:', err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => { load(); }, []);

  const metrics = data ? [
    { label: 'Total Members', value: data.metrics.totalMembers, icon: Users, color: 'accent' },
    { label: 'Online Now', value: data.metrics.onlineMembers, icon: Wifi, color: 'success' },
    { label: 'Active Projects', value: data.metrics.activeProjects, icon: FolderKanban, color: 'accent' },
    { label: 'Experiments', value: data.metrics.experiments, icon: FlaskConical, color: 'purple' },
    { label: 'Products', value: data.metrics.products, icon: Package, color: 'accent' },
    { label: 'Tasks', value: data.metrics.tasks, icon: CheckSquare, color: 'warning' },
    { label: 'Applications', value: data.metrics.applications, icon: ClipboardList, color: 'warning' },
    { label: 'AI Usage', value: data.metrics.aiUsage, icon: Bot, color: 'purple' },
  ] : [];

  const getAuditTypeColor = (type) => {
    if (type?.includes('XP')) return 'warning';
    if (type?.includes('ROLE')) return 'purple';
    if (type?.includes('SECURITY')) return 'danger';
    if (type?.includes('MEMBER')) return 'success';
    return 'accent';
  };

  const getActivityIcon = (type) => {
    const icons = {
      XP_CHANGED: '⚡',
      ROLE_CHANGED: '🛡️',
      MEMBER_UPDATED: '👤',
      CONTENT_MODERATED: '📋',
      SECURITY_CHANGED: '🔒',
      ACHIEVEMENT_GRANTED: '🏆',
      BADGE_GRANTED: '🎖️',
    };
    return icons[type] || '📌';
  };

  const togglePlatformLock = () => {
    if (platformLocked) {
      setPlatformLocked(false);
      setLockReason('');
    } else {
      const reason = prompt('Enter reason for platform lock:');
      if (reason) {
        setLockReason(reason);
        setPlatformLocked(true);
      }
    }
  };

  return (
    <div className="space-y-6">
      {/* Platform Lock Alert */}
      {platformLocked && (
        <Card className="border-red-500/50 bg-red-500/10">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Lock className="h-5 w-5 text-red-400" />
                <div>
                  <p className="font-bold text-white">Platform Locked</p>
                  <p className="text-sm text-text-muted">{lockReason}</p>
                </div>
              </div>
              <Button
                onClick={togglePlatformLock}
                size="sm"
                variant="destructive"
              >
                <Unlock className="h-4 w-4 mr-2" />
                Unlock Platform
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Metrics Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-heading text-section-title font-bold text-white">Platform Overview</h2>
          <p className="text-caption text-text-muted">Live stats across all BeastBuck systems</p>
        </div>
        <div className="flex items-center gap-3">
          <Button
            onClick={togglePlatformLock}
            size="sm"
            variant={platformLocked ? "destructive" : "secondary"}
            className={platformLocked ? "bg-red-600 hover:bg-red-700" : ""}
          >
            {platformLocked ? <Unlock className="h-4 w-4 mr-2" /> : <Lock className="h-4 w-4 mr-2" />}
            {platformLocked ? 'Unlock' : 'Lock Platform'}
          </Button>
          <button
            onClick={() => load(true)}
            disabled={refreshing}
            className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/5 px-4 py-2 text-caption font-bold text-text-soft transition-all hover:bg-white/10 hover:text-white hover:-translate-y-0.5 active:scale-95 disabled:opacity-50"
          >
            <RefreshCw className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>
      </div>

      {/* Metrics Grid */}
      {loading ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {Array.from({ length: 8 }).map((_, i) => (
            <div key={i} className="h-24 animate-pulse rounded-xl bg-white/5 border border-white/10" />
          ))}
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {metrics.map(m => <AdminMetric key={m.label} {...m} />)}
        </div>
      )}

      {/* Activity & Audit Grid */}
      <div className="grid gap-6 xl:grid-cols-2">
        <AdminPanel title="Recent Activity" icon={Activity}>
          {loading ? <LoadingRows count={4} /> : (
            <div className="space-y-2">
              {data?.recentActivity.length === 0 ? (
                <p className="py-6 text-center text-caption text-text-muted">No recent activity recorded.</p>
              ) : data?.recentActivity.map(item => (
                <div key={item.id} className="flex items-start gap-3 rounded-lg border border-white/10 bg-white/[0.02] p-3 transition-all duration-200 hover:bg-white/[0.04] hover:border-white/15 hover:shadow-depth-1">
                  <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-accent/10 text-sm">
                    📌
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-caption font-bold text-white">{item.title || item.type || 'Activity'}</p>
                    <p className="mt-0.5 truncate text-badge text-text-muted">{item.description || 'Activity recorded'}</p>
                  </div>
                  <span className="shrink-0 text-badge text-text-muted">
                    {item.timestamp ? formatDistanceToNow(item.timestamp) : '—'}
                  </span>
                </div>
              ))}
            </div>
          )}
        </AdminPanel>

        <AdminPanel title="Audit Trail" icon={ClipboardList}>
          {loading ? <LoadingRows count={4} /> : (
            <div className="space-y-2">
              {data?.auditLogs.length === 0 ? (
                <p className="py-6 text-center text-caption text-text-muted">No audit logs yet.</p>
              ) : data?.auditLogs.map(item => (
                <div key={item.id} className="flex items-start gap-3 rounded-lg border border-white/10 bg-white/[0.02] p-3 transition-all duration-200 hover:bg-white/[0.04] hover:border-white/15 hover:shadow-depth-1">
                  <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-white/5 text-sm">
                    {getActivityIcon(item.type)}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <p className="truncate text-caption font-bold text-white">{item.summary || item.type}</p>
                      <StatusBadge variant={getAuditTypeColor(item.type)}>
                        {item.type?.replace(/_/g, ' ')}
                      </StatusBadge>
                    </div>
                    <p className="mt-0.5 truncate text-badge text-text-muted">
                      Target: {item.targetId || 'system'} · Actor: {item.actorId?.slice(0, 8)}…
                    </p>
                  </div>
                  <span className="shrink-0 text-badge text-text-muted">
                    {item.createdAt ? formatDistanceToNow(item.createdAt) : '—'}
                  </span>
                </div>
              ))}
            </div>
          )}
        </AdminPanel>
      </div>

      {/* System Status */}
      <AdminPanel title="System Health" icon={Shield}>
        <div className="grid gap-3 sm:grid-cols-3">
          {data?.systemHealth ? data.systemHealth.map(({ label, status, color }) => (
            <div key={label} className="flex items-center justify-between rounded-lg border border-white/10 bg-white/[0.02] px-4 py-3 transition-all duration-200 hover:bg-white/[0.04] hover:border-white/15">
              <span className="text-caption text-text-soft">{label}</span>
              <StatusBadge variant={color}>{status}</StatusBadge>
            </div>
          )) : (
            <div className="col-span-3 text-center text-sm text-text-muted">System health data not available</div>
          )}
        </div>
      </AdminPanel>
    </div>
  );
}

