export default function ExecutiveRoleManagement() {
  const { user, roleData } = useAuth();
  const [members, setMembers] = useState([]);
  const [filteredMembers, setFilteredMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [selectedMember, setSelectedMember] = useState(null);
  const [showRoleModal, setShowRoleModal] = useState(false);
  const [showTransferModal, setShowTransferModal] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [stats, setStats] = useState({ total: 0, executives: 0, leaders: 0, members: 0 });

  const currentUserRole = roleData?.role;
  const isCEO = currentUserRole === ROLES.MAIN_CEO;
  const isCoCEO = currentUserRole === ROLES.CO_CEO;
  const hasAccess = isCEO || isCoCEO;
  const permissions = ROLE_PERMISSIONS[currentUserRole] || {};

  useEffect(() => {
    if (!hasAccess) {
      toast.error('Access denied. CEO and Co-CEO only.');
      return;
    }
    loadMembers();
  }, [hasAccess]);

  useEffect(() => {
    filterMembers();
  }, [members, searchQuery, roleFilter]);

  const loadMembers = async () => {
    setLoading(true);
    try {
      const usersRef = collection(db, 'users');
      const snapshot = await getDocs(usersRef);
      const membersList = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      setMembers(membersList);
      setFilteredMembers(membersList);

      // Calculate stats
      setStats({
        total: membersList.length,
        executives: membersList.filter(m => m.role === ROLES.MAIN_CEO || m.role === ROLES.CO_CEO).length,
        leaders: membersList.filter(m => m.role === ROLES.LEADER).length,
        members: membersList.filter(m => m.role === ROLES.MEMBER).length,
      });
    } catch (error) {
      console.error('Error loading members:', error);
      toast.error('Failed to load members');
    } finally {
      setLoading(false);
    }
  };

  const filterMembers = () => {
    let filtered = [...members];

    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(m => 
        (m.displayName || m.username || '').toLowerCase().includes(query) ||
        (m.email || '').toLowerCase().includes(query)
      );
    }

    if (roleFilter !== 'all') {
      filtered = filtered.filter(m => m.role === roleFilter);
    }

    setFilteredMembers(filtered);
  };

  const handleRoleChange = async (memberId, newRole) => {
    setActionLoading(true);
    try {
      const memberRef = doc(db, 'users', memberId);
      await updateDoc(memberRef, {
        role: newRole,
        roleUpdatedAt: serverTimestamp(),
        roleUpdatedBy: user.uid
      });

      toast.success(`Role updated successfully`);
      await loadMembers();
      setShowRoleModal(false);
      setSelectedMember(null);
    } catch (error) {
      console.error('Error updating role:', error);
      toast.error('Failed to update role');
    } finally {
      setActionLoading(false);
    }
  };

  const handleRemoveCoCEO = async (coCEOMemberId) => {
    if (!window.confirm('Are you sure you want to remove this Co-CEO? They will be demoted to Member.')) {
      return;
    }

    setActionLoading(true);
    try {
      await runTransaction(db, async (transaction) => {
        const coCEORef = doc(db, 'users', coCEOMemberId);
        const coCEODoc = await transaction.get(coCEORef);

        if (!coCEODoc.exists()) {
          throw new Error('Co-CEO not found');
        }

        const coCEOData = coCEODoc.data();
        if (coCEOData.role !== ROLES.CO_CEO) {
          throw new Error('User is not a Co-CEO');
        }

        transaction.update(coCEORef, {
          role: ROLES.MEMBER,
          isExecutive: false,
          demotedBy: user.uid,
          demotedAt: serverTimestamp(),
          updatedAt: serverTimestamp()
        });
      });

      toast.success('Co-CEO removed successfully');
      await loadMembers();
    } catch (error) {
      console.error('Error removing Co-CEO:', error);
      toast.error(error.message || 'Failed to remove Co-CEO');
    } finally {
      setActionLoading(false);
    }
  };

  const handlePromoteToCoCEO = async (memberId) => {
    if (!window.confirm('Are you sure you want to promote this member to Co-CEO?')) {
      return;
    }

    setActionLoading(true);
    try {
      await runTransaction(db, async (transaction) => {
        const memberRef = doc(db, 'users', memberId);
        const memberDoc = await transaction.get(memberRef);

        if (!memberDoc.exists()) {
          throw new Error('Member not found');
        }

        const memberData = memberDoc.data();
        if (memberData.role === ROLES.MAIN_CEO || memberData.role === ROLES.CO_CEO) {
          throw new Error('User is already an executive');
        }

        transaction.update(memberRef, {
          role: ROLES.CO_CEO,
          isExecutive: true,
          promotedBy: user.uid,
          promotedAt: serverTimestamp(),
          updatedAt: serverTimestamp()
        });
      });

      toast.success('Member promoted to Co-CEO successfully');
      await loadMembers();
    } catch (error) {
      console.error('Error promoting to Co-CEO:', error);
      toast.error(error.message || 'Failed to promote to Co-CEO');
    } finally {
      setActionLoading(false);
    }
  };

  const handleTransferCEO = async (newCEOId) => {
    if (!window.confirm('Are you sure you want to transfer CEO position? This will remove your CEO status and cannot be undone.')) {
      return;
    }

    setActionLoading(true);
    try {
      await runTransaction(db, async (transaction) => {
        const currentCEORef = doc(db, 'users', user.uid);
        const newCEORef = doc(db, 'users', newCEOId);

        const currentCEODoc = await transaction.get(currentCEORef);
        const newCEODoc = await transaction.get(newCEORef);

        if (!currentCEODoc.exists() || !newCEODoc.exists()) {
          throw new Error('User not found');
        }

        const currentCEOData = currentCEODoc.data();
        if (currentCEOData.role !== ROLES.MAIN_CEO) {
          throw new Error('You are not the current CEO');
        }

        const newCEOData = newCEODoc.data();
        if (newCEOData.role === ROLES.MAIN_CEO) {
          throw new Error('User is already the CEO');
        }

        // Demote current CEO to Co-CEO
        transaction.update(currentCEORef, {
          role: ROLES.CO_CEO,
          ceoTransferredTo: newCEOId,
          ceoTransferredAt: serverTimestamp(),
          updatedAt: serverTimestamp()
        });

        // Promote new user to CEO
        transaction.update(newCEORef, {
          role: ROLES.MAIN_CEO,
          isExecutive: true,
          ceoTransferredFrom: user.uid,
          ceoTransferredAt: serverTimestamp(),
          updatedAt: serverTimestamp()
        });
      });

      toast.success('CEO position transferred successfully');
      await loadMembers();
      setShowTransferModal(false);
    } catch (error) {
      console.error('Error transferring CEO:', error);
      toast.error(error.message || 'Failed to transfer CEO position');
    } finally {
      setActionLoading(false);
    }
  };

  const getRoleInfo = (role) => ROLE_HIERARCHY[role] || ROLE_HIERARCHY[ROLES.USER];

  const canModifyRole = (targetMember) => {
    if (!hasAccess) return false;

    const targetRole = targetMember.role;

    // CEO can modify everyone except when transferring their own position
    if (isCEO) {
      return true;
    }

    // Co-CEO cannot modify CEO or other Co-CEOs
    if (isCoCEO) {
      return targetRole !== ROLES.MAIN_CEO && targetRole !== ROLES.CO_CEO;
    }

    return false;
  };

  const canRemoveCoCEO = (targetMember) => {
    return isCEO && targetMember.role === ROLES.CO_CEO;
  };

  const canPromoteToCoCEO = (targetMember) => {
    return isCEO && targetMember.role !== ROLES.MAIN_CEO && targetMember.role !== ROLES.CO_CEO;
  };

  const canTransferCEO = (targetMember) => {
    return isCEO && targetMember.id !== user.id && targetMember.role !== ROLES.MAIN_CEO;
  };

  if (!hasAccess) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="text-center">
          <Lock className="w-16 h-16 mx-auto text-text-muted mb-4" />
          <h2 className="text-2xl font-bold text-white mb-2">Access Denied</h2>
          <p className="text-text-muted">This page is only accessible to CEO and Co-CEO</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="relative overflow-hidden rounded-2xl border border-border bg-gradient-to-br from-surface/90 via-surface/70 to-accent/5 p-1 shadow-[0_0_40px_rgba(0,240,255,0.05)]">
        <div className="rounded-xl bg-black/30 p-6">
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <div className="flex items-center gap-4">
              <div className="relative flex h-14 w-14 items-center justify-center rounded-xl bg-gradient-to-br from-accent/20 to-accent-alt/20 text-accent shadow-[0_0_20px_rgba(0,240,255,0.2)]">
                <Crown className="h-7 w-7" />
                <span className="absolute -right-1 -top-1 h-3 w-3 rounded-full bg-status-success shadow-[0_0_8px_rgba(0,255,136,0.8)]" />
              </div>
              <div>
                <h1 className="font-heading text-2xl font-black tracking-wide text-white md:text-3xl">
                  Executive Role Management
                </h1>
                <p className="text-sm text-text-muted">
                  {isCEO ? 'CEO Control Panel' : 'Co-CEO Management Panel'}
                </p>
              </div>
            </div>

            <div className="flex gap-2">
              <button
                onClick={loadMembers}
                disabled={loading}
                className="flex items-center gap-2 rounded-xl border border-border bg-white/5 px-4 py-2.5 text-sm font-bold text-text-soft hover:bg-white/10 hover:text-white transition-all disabled:opacity-50"
              >
                <RefreshCw className={cn("h-4 w-4", loading && "animate-spin")} />
                Refresh
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <StatCard
          icon={Users}
          label="Total Members"
          value={stats.total}
          color="text-blue-400"
          bgColor="bg-blue-400/10"
        />
        <StatCard
          icon={Crown}
          label="Executives"
          value={stats.executives}
          color="text-yellow-400"
          bgColor="bg-yellow-400/10"
        />
        <StatCard
          icon={Shield}
          label="Leaders"
          value={stats.leaders}
          color="text-purple-400"
          bgColor="bg-purple-400/10"
        />
        <StatCard
          icon={Award}
          label="Members"
          value={stats.members}
          color="text-green-400"
          bgColor="bg-green-400/10"
        />
      </div>

      {/* Search and Filter */}
      <div className="flex flex-col gap-4 md:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-text-muted" />
          <input
            type="text"
            placeholder="Search members by name, username, or email..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="h-12 w-full rounded-xl border border-border bg-white/5 pl-12 pr-4 text-sm text-white placeholder:text-text-muted focus:border-accent/40 focus:outline-none focus:ring-2 focus:ring-accent/20"
          />
        </div>

        <div className="relative">
          <select
            value={roleFilter}
            onChange={(e) => setRoleFilter(e.target.value)}
            className="h-12 appearance-none rounded-xl border border-border bg-white/5 px-4 pr-12 text-sm text-white focus:border-accent/40 focus:outline-none focus:ring-2 focus:ring-accent/20"
          >
            <option value="all">All Roles</option>
            {AVAILABLE_ROLES.map(role => (
              <option key={role} value={role}>{getRoleInfo(role).label}</option>
            ))}
          </select>
          <ChevronDown className="absolute right-4 top-1/2 h-5 w-5 -translate-y-1/2 text-text-muted pointer-events-none" />
        </div>
      </div>

      {/* Members List */}
      <div className="rounded-2xl border border-border bg-white/[0.02] overflow-hidden">
        <div className="border-b border-border bg-white/[0.02] px-6 py-4">
          <h3 className="text-lg font-bold text-white">Team Members</h3>
          <p className="text-sm text-text-muted">Manage roles and permissions</p>
        </div>

        {loading ? (
          <div className="p-8 text-center">
            <RefreshCw className="h-8 w-8 mx-auto animate-spin text-accent mb-4" />
            <p className="text-text-muted">Loading members...</p>
          </div>
        ) : filteredMembers.length === 0 ? (
          <div className="p-8 text-center">
            <Users className="h-12 w-12 mx-auto text-text-muted mb-4" />
            <p className="text-text-muted">No members found</p>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {filteredMembers.map((member, index) => {
              const roleInfo = getRoleInfo(member.role);
              const RoleIcon = roleInfo.icon;
              const isCurrentUser = member.id === user.id;

              return (
                <div
                  key={member.id}
                  className="group relative px-6 py-4 transition-all hover:bg-white/[0.03]"
                  style={{ animationDelay: `${index * 50}ms` }}
                >
                  <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                    {/* Member Info */}
                    <div className="flex items-center gap-4">
                      <div className={cn(
                        "flex h-12 w-12 items-center justify-center rounded-xl",
                        roleInfo.bgColor,
                        roleInfo.color
                      )}>
                        <RoleIcon className="h-6 w-6" />
                      </div>

                      <div className="min-w-0">
                        <div className="flex items-center gap-2">
                          <h4 className="font-bold text-white truncate">
                            {member.displayName || member.username || 'Unknown'}
                          </h4>
                          {isCurrentUser && (
                            <span className="flex items-center gap-1 rounded-full bg-accent/10 px-2 py-0.5 text-xs font-bold text-accent">
                              <Star className="h-3 w-3" />
                              You
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-text-muted truncate">
                          {member.email || member.username || 'No email'}
                        </p>
                      </div>
                    </div>

                    {/* Role Badge */}
                    <div className="flex items-center gap-3">
                      <span className={cn(
                        "inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-bold",
                        roleInfo.bgColor,
                        roleInfo.color
                      )}>
                        <RoleIcon className="h-4 w-4" />
                        {roleInfo.label}
                      </span>

                      {/* Actions */}
                      <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        {canModifyRole(member) && !isCurrentUser && (
                          <button
                            onClick={() => {
                              setSelectedMember(member);
                              setShowRoleModal(true);
                            }}
                            className="flex items-center gap-1.5 rounded-lg bg-accent/10 px-3 py-2 text-sm font-bold text-accent hover:bg-accent/20 transition-all"
                          >
                            <Edit className="h-4 w-4" />
                            Change Role
                          </button>
                        )}

                        {canRemoveCoCEO(member) && (
                          <button
                            onClick={() => handleRemoveCoCEO(member.id)}
                            disabled={actionLoading}
                            className="flex items-center gap-1.5 rounded-lg bg-red-500/10 px-3 py-2 text-sm font-bold text-red-400 hover:bg-red-500/20 transition-all disabled:opacity-50"
                          >
                            <UserMinus className="h-4 w-4" />
                            Remove Co-CEO
                          </button>
                        )}

                        {canPromoteToCoCEO(member) && (
                          <button
                            onClick={() => handlePromoteToCoCEO(member.id)}
                            disabled={actionLoading}
                            className="flex items-center gap-1.5 rounded-lg bg-purple-500/10 px-3 py-2 text-sm font-bold text-purple-400 hover:bg-purple-500/20 transition-all disabled:opacity-50"
                          >
                            <Crown className="h-4 w-4" />
                            Make Co-CEO
                          </button>
                        )}

                        {canTransferCEO(member) && (
                          <button
                            onClick={() => {
                              setSelectedMember(member);
                              setShowTransferModal(true);
                            }}
                            disabled={actionLoading}
                            className="flex items-center gap-1.5 rounded-lg bg-yellow-500/10 px-3 py-2 text-sm font-bold text-yellow-400 hover:bg-yellow-500/20 transition-all disabled:opacity-50"
                          >
                            <RefreshCw className="h-4 w-4" />
                            Transfer CEO
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Role Change Modal */}
      {showRoleModal && selectedMember && (
        <Modal
          isOpen={showRoleModal}
          onClose={() => {
            setShowRoleModal(false);
            setSelectedMember(null);
          }}
          title={`Change Role for ${selectedMember.displayName || selectedMember.username}`}
        >
          <div className="space-y-4">
            <p className="text-sm text-text-muted">
              Select a new role for this member. This action will be logged.
            </p>

            <div className="space-y-2">
              {AVAILABLE_ROLES.map(role => {
                const roleInfo = getRoleInfo(role);
                const RoleIcon = roleInfo.icon;
                const isCurrentRole = selectedMember.role === role;

                // Co-CEO cannot assign CEO or Co-CEO roles
                if (isCoCEO && (role === ROLES.MAIN_CEO || role === ROLES.CO_CEO)) {
                  return null;
                }

                return (
                  <button
                    key={role}
                    onClick={() => handleRoleChange(selectedMember.id, role)}
                    disabled={actionLoading || isCurrentRole}
                    className={cn(
                      "w-full flex items-center gap-3 rounded-xl border p-4 text-left transition-all",
                      isCurrentRole
                        ? "border-accent/40 bg-accent/5 cursor-default"
                        : "border-border bg-white/[0.02] hover:border-white/10 hover:bg-white/[0.04]",
                      actionLoading && "opacity-50 cursor-not-allowed"
                    )}
                  >
                    <div className={cn(
                      "flex h-10 w-10 items-center justify-center rounded-lg",
                      roleInfo.bgColor,
                      roleInfo.color
                    )}>
                      <RoleIcon className="h-5 w-5" />
                    </div>

                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-white">{roleInfo.label}</span>
                        {isCurrentRole && (
                          <span className="rounded-full bg-accent/10 px-2 py-0.5 text-xs font-bold text-accent">
                            Current
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-text-muted">
                        Level {roleInfo.level} access
                      </p>
                    </div>

                    {!isCurrentRole && (
                      <div className="flex h-6 w-6 items-center justify-center rounded-full border border-border bg-white/5">
                        <ChevronDown className="h-4 w-4 text-text-muted" />
                      </div>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        </Modal>
      )}

      {/* CEO Transfer Modal */}
      {showTransferModal && selectedMember && (
        <Modal
          isOpen={showTransferModal}
          onClose={() => {
            setShowTransferModal(false);
            setSelectedMember(null);
          }}
          title="Transfer CEO Position"
          variant="danger"
        >
          <div className="space-y-4">
            <div className="flex items-start gap-3 rounded-xl bg-red-500/10 border border-red-500/20 p-4">
              <AlertTriangle className="h-5 w-5 text-red-400 mt-0.5 shrink-0" />
              <div>
                <h4 className="font-bold text-red-400">Warning: Irreversible Action</h4>
                <p className="text-sm text-text-muted mt-1">
                  This will transfer your CEO position to {selectedMember.displayName || selectedMember.username}. 
                  You will be demoted to Co-CEO and this action cannot be undone.
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4 rounded-xl bg-white/[0.02] border border-border p-4">
              <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-yellow-400/10 text-yellow-400">
                <Crown className="h-6 w-6" />
              </div>
              <div>
                <h4 className="font-bold text-white">
                  {selectedMember.displayName || selectedMember.username}
                </h4>
                <p className="text-sm text-text-muted">
                  {selectedMember.email || selectedMember.username}
                </p>
              </div>
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => handleTransferCEO(selectedMember.id)}
                disabled={actionLoading}
                className="flex-1 flex items-center justify-center gap-2 rounded-xl bg-red-500 py-3 text-sm font-bold text-white hover:bg-red-600 transition-all disabled:opacity-50"
              >
                <RefreshCw className={cn("h-4 w-4", actionLoading && "animate-spin")} />
                {actionLoading ? 'Transferring...' : 'Confirm Transfer'}
              </button>
              <button
                onClick={() => {
                  setShowTransferModal(false);
                  setSelectedMember(null);
                }}
                disabled={actionLoading}
                className="flex-1 rounded-xl border border-border bg-white/5 py-3 text-sm font-bold text-text-soft hover:bg-white/10 transition-all disabled:opacity-50"
              >
                Cancel
              </button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// Stat Card Component
function StatCard({ icon: Icon, label, value, color, bgColor }) {
  return (
    <div className="relative overflow-hidden rounded-xl border border-border bg-white/[0.02] p-4 transition-all hover:border-white/10 hover:bg-white/[0.04]">
      <div className="flex items-center gap-3">
        <div className={cn("flex h-10 w-10 items-center justify-center rounded-lg", bgColor, color)}>
          <Icon className="h-5 w-5" />
        </div>
        <div>
          <p className="text-2xl font-bold text-white">{value}</p>
          <p className="text-xs text-text-muted">{label}</p>
        </div>
      </div>
    </div>
  );
}

// Modal Component
function Modal({ isOpen, onClose, title, children, variant = 'default' }) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />
      <div className={cn(
        "relative w-full max-w-md rounded-2xl border bg-background p-6 shadow-2xl",
        variant === 'danger' ? "border-red-500/30" : "border-border"
      )}>
        <div className="mb-4 flex items-center justify-between">
          <h3 className="text-lg font-bold text-white">{title}</h3>
          <button
            onClick={onClose}
            className="flex h-8 w-8 items-center justify-center rounded-lg border border-border bg-white/5 text-text-muted hover:bg-white/10 hover:text-white transition-all"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useAuth } from '../auth/AuthContext';
import { Shield, Lock, Key, FileText, Server, UserCheck, AlertTriangle, CheckCircle } from 'lucide-react';
import { PageContainer } from '@frontend/components/layout/LayoutWrappers';
import { PageHeader } from '@frontend/components/ui/UIElements';
import { Card, CardContent } from '@frontend/components/ui/Card';
import Button from '@frontend/components/ui/Button';
import { hasPermission } from '@shared/permissions/permissions';

export default function ExecutiveSecurity() {
  const { user, roleData } = useAuth();

  const securityFeatures = [
    { id: 'rbac', name: 'Role-Based Access Control (RBAC)', icon: Shield, color: 'emerald', status: 'active', description: 'Granular permissions based on user roles' },
    { id: 'firestore', name: 'Firestore Security Rules', icon: Lock, color: 'blue', status: 'active', description: 'Database-level access control' },
    { id: 'auth', name: 'Firebase Authentication', icon: Key, color: 'purple', status: 'active', description: 'Secure user authentication' },
    { id: 'audit', name: 'Audit Logs', icon: FileText, color: 'amber', status: 'active', description: 'Immutable activity tracking' },
    { id: 'permission', name: 'Permission Validation', icon: UserCheck, color: 'cyan', status: 'active', description: 'Server-side permission checks' },
    { id: 'server', name: 'Server-side Authorization', icon: Server, color: 'red', status: 'active', description: 'No client-side trust' },
    { id: 'session', name: 'Session Validation', icon: Lock, color: 'orange', status: 'active', description: 'Active session management' },
  ];

  const securityMetrics = [
    { id: 'active-sessions', name: 'Active Sessions', value: '127', trend: '+5%' },
    { id: 'auth-attempts', name: 'Auth Attempts (24h)', value: '1,234', trend: '+12%' },
    { id: 'failed-logins', name: 'Failed Logins (24h)', value: '23', trend: '-8%' },
    { id: 'security-events', name: 'Security Events (24h)', value: '5', trend: '0%' },
  ];

  const recentSecurityEvents = [
    { id: 1, type: 'Role Change', user: 'Admin', action: 'Promoted user to Co-CEO', time: '2 hours ago', severity: 'info' },
    { id: 2, type: 'Login Alert', user: 'Unknown', action: 'Failed login attempt from unusual location', time: '4 hours ago', severity: 'warning' },
    { id: 3, type: 'Permission Update', user: 'CEO', action: 'Updated department permissions', time: '6 hours ago', severity: 'info' },
    { id: 4, type: 'Session Revoked', user: 'Admin', action: 'Revoked session for suspended user', time: '1 day ago', severity: 'warning' },
  ];

  const getColorClass = (color) => {
    const colors = {
      emerald: 'bg-emerald-500/20 border-emerald-500/30 text-emerald-400',
      blue: 'bg-blue-500/20 border-blue-500/30 text-blue-400',
      purple: 'bg-purple-500/20 border-purple-500/30 text-purple-400',
      amber: 'bg-amber-500/20 border-amber-500/30 text-amber-400',
      cyan: 'bg-cyan-500/20 border-cyan-500/30 text-cyan-400',
      red: 'bg-red-500/20 border-red-500/30 text-red-400',
      orange: 'bg-orange-500/20 border-orange-500/30 text-orange-400',
    };
    return colors[color] || colors.emerald;
  };

  const getSeverityClass = (severity) => {
    const severities = {
      info: 'bg-blue-500/10 border-blue-500/30 text-blue-400',
      warning: 'bg-amber-500/10 border-amber-500/30 text-amber-400',
      critical: 'bg-red-500/10 border-red-500/30 text-red-400',
    };
    return severities[severity] || severities.info;
  };

  if (!hasPermission(roleData?.role, 'canAccessCeoPanel')) {
    return (
      <PageContainer>
        <div className="flex items-center justify-center py-20">
          <div className="text-center">
            <Shield className="mx-auto h-12 w-12 text-text-muted mb-4" />
            <h1 className="text-2xl font-bold text-white mb-4">Access Denied</h1>
            <p className="text-text-muted">Executive Security is only accessible to CEO and Co-CEOs.</p>
          </div>
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer>
      <PageHeader 
        title="Executive Security" 
        description="Role-Based Access Control (RBAC), Firestore Security Rules, Firebase Authentication, Audit Logs, Permission Validation, Server-side Authorization, and Session Validation with no client-side trust."
        hero={true}
      />

      <Card>
        <CardContent className="p-6">
          <div className="flex items-center gap-2 mb-6">
            <Shield className="h-5 w-5 text-accent" />
            <h3 className="font-bold text-white text-xl">Security Features</h3>
          </div>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {securityFeatures.map((feature) => {
              const Icon = feature.icon;
              return (
                <div key={feature.id} className="p-4 rounded-xl bg-white/5 border border-border">
                  <div className={`p-3 rounded-xl ${getColorClass(feature.color)} mb-3`}>
                    <Icon className="h-6 w-6" />
                  </div>
                  <h4 className="font-bold text-white mb-1">{feature.name}</h4>
                  <p className="text-text-muted text-sm mb-2">{feature.description}</p>
                  <span className={`px-2 py-1 rounded-full text-xs font-bold ${feature.status === 'active' ? 'bg-emerald-500/10 text-emerald-400' : 'bg-amber-500/10 text-amber-400'}`}>
                    {feature.status.toUpperCase()}
                  </span>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      <Card className="mt-6">
        <CardContent className="p-6">
          <div className="flex items-center gap-2 mb-6">
            <Server className="h-5 w-5 text-accent" />
            <h3 className="font-bold text-white text-xl">Security Metrics</h3>
          </div>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {securityMetrics.map((metric) => (
              <div key={metric.id} className="p-4 rounded-xl bg-white/5 border border-border">
                <p className="text-text-muted text-sm mb-1">{metric.name}</p>
                <p className="text-2xl font-bold text-white mb-1">{metric.value}</p>
                <p className={`text-sm ${metric.trend.startsWith('+') ? 'text-emerald-400' : metric.trend.startsWith('-') ? 'text-red-400' : 'text-text-muted'}`}>
                  {metric.trend}
                </p>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      <Card className="mt-6">
        <CardContent className="p-6">
          <div className="flex items-center gap-2 mb-6">
            <FileText className="h-5 w-5 text-accent" />
            <h3 className="font-bold text-white text-xl">Recent Security Events</h3>
          </div>
          <div className="space-y-3">
            {recentSecurityEvents.map((event) => (
              <div key={event.id} className="p-4 rounded-xl bg-white/5 border border-border">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-white font-bold">{event.type}</span>
                  <span className={`px-2 py-1 rounded-full text-xs font-bold ${getSeverityClass(event.severity)}`}>
                    {event.severity.toUpperCase()}
                  </span>
                </div>
                <p className="text-text-muted text-sm mb-1">{event.action}</p>
                <div className="flex items-center justify-between">
                  <span className="text-text-muted text-xs">By: {event.user}</span>
                  <span className="text-text-muted text-xs">{event.time}</span>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      <Card className="mt-6">
        <CardContent className="p-6">
          <h3 className="font-bold text-white text-xl mb-4">Security Principles</h3>
          <div className="space-y-3">
            <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5">
              <CheckCircle className="h-5 w-5 text-emerald-400" />
              <span className="text-white">No client-side trust - all validations server-side</span>
            </div>
            <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5">
              <CheckCircle className="h-5 w-5 text-emerald-400" />
              <span className="text-white">Immutable audit logs for all actions</span>
            </div>
            <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5">
              <CheckCircle className="h-5 w-5 text-emerald-400" />
              <span className="text-white">Granular RBAC with principle of least privilege</span>
            </div>
            <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5">
              <CheckCircle className="h-5 w-5 text-emerald-400" />
              <span className="text-white">Real-time security monitoring and alerts</span>
            </div>
            <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5">
              <CheckCircle className="h-5 w-5 text-emerald-400" />
              <span className="text-white">Automatic session revocation on role changes</span>
            </div>
          </div>
        </CardContent>
      </Card>

      <Button className="w-full mt-6 bg-purple-600 hover:bg-purple-700">
        Review Security Settings
      </Button>
    </PageContainer>
  );
}

import { useState, useEffect } from 'react';
import { useAuth } from "../auth/AuthContext";
import { hasPermission } from '@shared/permissions/permissions';
import { collection, getDocs, query, where, orderBy, doc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { db } from '@services/firebase/config';
import { CheckCircle, XCircle, Clock, Search, User, Mail, Calendar, FileText, Info, ShieldAlert, UserPlus, Ban, AlertTriangle, Crown, Users, Building2, History, Award } from 'lucide-react';
import { PageContainer } from '@frontend/components/layout/LayoutWrappers';
import { PageHeader } from '@frontend/components/ui/UIElements';
import { Card, CardContent } from '@frontend/components/ui/Card';
import Button from '@frontend/components/ui/Button';
import { Input } from '@frontend/components/ui/Input';
import { cn } from '@shared/lib/utils';

export default function MembershipCenter() {
  const { user, roleData } = useAuth();
  const [applications, setApplications] = useState([]);
  const [members, setMembers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [statusFilter, setStatusFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [selectedMember, setSelectedMember] = useState(null);
  const [reviewNotes, setReviewNotes] = useState('');
  const [submittingReview, setSubmittingReview] = useState(false);
  const [error, setError] = useState(null);
  const [actionType, setActionType] = useState(null);
  const [activeTab, setActiveTab] = useState('applications');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      // Load applications
      const applicationsQuery = query(
        collection(db, 'users'),
        where('membershipStatus', '==', 'pending'),
        orderBy('createdAt', 'desc')
      );
      const applicationsSnapshot = await getDocs(applicationsQuery);
      const applicationsData = applicationsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setApplications(applicationsData);

      // Load members
      const membersQuery = query(
        collection(db, 'users'),
        where('membershipStatus', '==', 'approved'),
        orderBy('createdAt', 'desc')
      );
      const membersSnapshot = await getDocs(membersQuery);
      const membersData = membersSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setMembers(membersData);
    } catch (error) {
      console.error('Error loading membership data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleApplicationAction = async (action, applicationId) => {
    const app = applications.find(a => a.id === applicationId);
    if (!app) return;

    setSubmittingReview(true);
    setError(null);

    try {
      const appRef = doc(db, 'users', applicationId);
      let updateData = { updatedAt: serverTimestamp() };

      switch(action) {
        case 'approve':
          updateData.membershipStatus = 'approved';
          updateData.accountStatus = 'active';
          updateData.approvedAt = serverTimestamp();
          updateData.approvedBy = user.uid;
          break;
        case 'reject':
          updateData.membershipStatus = 'rejected';
          updateData.rejectedAt = serverTimestamp();
          updateData.rejectedBy = user.uid;
          updateData.rejectionReason = reviewNotes;
          break;
        case 'request_info':
          updateData.membershipStatus = 'pending';
          updateData.needsInfo = true;
          updateData.infoRequestedAt = serverTimestamp();
          updateData.infoRequestedBy = user.uid;
          break;
        case 'promote':
          updateData.accountStatus = 'premium';
          break;
        case 'suspend':
          updateData.accountStatus = 'suspended';
          updateData.suspendedAt = serverTimestamp();
          updateData.suspendedBy = user.uid;
          break;
        case 'ban':
          updateData.accountStatus = 'banned';
          updateData.membershipStatus = 'rejected';
          updateData.bannedAt = serverTimestamp();
          updateData.bannedBy = user.uid;
          break;
      }

      await updateDoc(appRef, updateData);
      await loadData();
      setSelectedApplication(null);
      setReviewNotes('');
      setActionType(null);
    } catch (err) {
      console.error('Error handling action:', err);
      setError('Failed to process action');
    } finally {
      setSubmittingReview(false);
    }
  };

  const handleMemberAction = async (action, memberId) => {
    const member = members.find(m => m.id === memberId);
    if (!member) return;

    setSubmittingReview(true);
    setError(null);

    try {
      const memberRef = doc(db, 'users', memberId);
      let updateData = { updatedAt: serverTimestamp() };

      switch(action) {
        case 'promote_co_ceo':
          updateData.role = 'Co-CEO';
          updateData.isExecutive = true;
          updateData.promotedBy = user.uid;
          updateData.promotedAt = serverTimestamp();
          break;
        case 'assign_leadership':
          updateData.role = 'Leader';
          break;
        case 'assign_moderator':
          updateData.role = 'Moderator';
          break;
        case 'assign_mentor':
          updateData.role = 'Mentor';
          break;
        case 'suspend':
          updateData.accountStatus = 'suspended';
          updateData.suspendedAt = serverTimestamp();
          updateData.suspendedBy = user.uid;
          break;
        case 'ban':
          updateData.accountStatus = 'banned';
          updateData.membershipStatus = 'rejected';
          updateData.bannedAt = serverTimestamp();
          updateData.bannedBy = user.uid;
          break;
      }

      await updateDoc(memberRef, updateData);
      await loadData();
      setSelectedMember(null);
      setReviewNotes('');
      setActionType(null);
    } catch (err) {
      console.error('Error handling member action:', err);
      setError('Failed to process action');
    } finally {
      setSubmittingReview(false);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'approved': return 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20';
      case 'rejected': return 'text-red-400 bg-red-500/10 border-red-500/20';
      case 'pending': return 'text-amber-400 bg-amber-500/10 border-amber-500/20';
      default: return 'text-text-muted bg-white/5 border-border';
    }
  };

  const getAccountStatusColor = (status) => {
    switch (status) {
      case 'active': return 'text-emerald-400 bg-emerald-500/10';
      case 'premium': return 'text-purple-400 bg-purple-500/10';
      case 'suspended': return 'text-amber-400 bg-amber-500/10';
      case 'banned': return 'text-red-400 bg-red-500/10';
      default: return 'text-text-muted bg-white/5';
    }
  };

  const getRoleColor = (role) => {
    switch (role) {
      case 'CEO': return 'text-purple-400 bg-purple-500/10 border-purple-500/20';
      case 'Co-CEO': return 'text-blue-400 bg-blue-500/10 border-blue-500/20';
      case 'Leader': return 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20';
      case 'Moderator': return 'text-amber-400 bg-amber-500/10 border-amber-500/20';
      case 'Mentor': return 'text-pink-400 bg-pink-500/10 border-pink-500/20';
      default: return 'text-text-muted bg-white/5 border-border';
    }
  };

  if (!hasPermission(roleData?.role, 'canAccessCeoPanel')) {
    return (
      <PageContainer>
        <div className="flex items-center justify-center py-20">
          <div className="text-center">
            <ShieldAlert className="mx-auto h-12 w-12 text-text-muted mb-4" />
            <h1 className="text-2xl font-bold text-white mb-4">Access Denied</h1>
            <p className="text-text-muted">Membership Center is only accessible to executives.</p>
          </div>
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer>
      <PageHeader 
        title="Membership Center" 
        description="Executive management of membership applications, member accounts, and organizational structure."
        hero={true}
      />

      {/* Stats Overview */}
      <div className="grid gap-4 sm:grid-cols-4 mb-6">
        <Card className="bg-gradient-to-br from-amber-500/10 to-orange-500/10 border-amber-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <UserPlus className="h-5 w-5 text-amber-400" />
              <span className="text-xs px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-400">Pending</span>
            </div>
            <p className="text-2xl font-bold text-white">{applications.length}</p>
            <p className="text-xs text-text-muted">Pending Applications</p>
          </CardContent>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500/10 to-green-500/10 border-emerald-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <CheckCircle className="h-5 w-5 text-emerald-400" />
              <span className="text-xs px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-400">Approved</span>
            </div>
            <p className="text-2xl font-bold text-white">{members.length}</p>
            <p className="text-xs text-text-muted">Approved Members</p>
          </CardContent>
        </Card>
        <Card className="bg-gradient-to-br from-amber-500/10 to-yellow-500/10 border-amber-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <AlertTriangle className="h-5 w-5 text-amber-400" />
              <span className="text-xs px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-400">Suspended</span>
            </div>
            <p className="text-2xl font-bold text-white">{members.filter(m => m.accountStatus === 'suspended').length}</p>
            <p className="text-xs text-text-muted">Suspended Accounts</p>
          </CardContent>
        </Card>
        <Card className="bg-gradient-to-br from-red-500/10 to-rose-500/10 border-red-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <Ban className="h-5 w-5 text-red-400" />
              <span className="text-xs px-2 py-0.5 rounded-full bg-red-500/10 text-red-400">Banned</span>
            </div>
            <p className="text-2xl font-bold text-white">{members.filter(m => m.accountStatus === 'banned').length}</p>
            <p className="text-xs text-text-muted">Banned Accounts</p>
          </CardContent>
        </Card>
      </div>

      {/* Tab Navigation */}
      <Card className="mb-6">
        <CardContent className="p-4">
          <div className="flex gap-2">
            <button
              onClick={() => setActiveTab('applications')}
              className={cn(
                "flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all",
                activeTab === 'applications'
                  ? "bg-accent/10 text-accent border border-accent/30"
                  : "text-text-muted hover:bg-white/5 hover:text-white"
              )}
            >
              <FileText className="h-4 w-4" />
              Applications ({applications.length})
            </button>
            <button
              onClick={() => setActiveTab('members')}
              className={cn(
                "flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all",
                activeTab === 'members'
                  ? "bg-accent/10 text-accent border border-accent/30"
                  : "text-text-muted hover:bg-white/5 hover:text-white"
              )}
            >
              <Users className="h-4 w-4" />
              Members ({members.length})
            </button>
            <button
              onClick={() => setActiveTab('history')}
              className={cn(
                "flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all",
                activeTab === 'history'
                  ? "bg-accent/10 text-accent border border-accent/30"
                  : "text-text-muted hover:bg-white/5 hover:text-white"
              )}
            >
              <History className="h-4 w-4" />
              History
            </button>
          </div>
        </CardContent>
      </Card>

      {/* Applications Tab */}
      {activeTab === 'applications' && (
        <Card>
          <CardContent className="p-6">
            {loading ? (
              <div className="flex items-center justify-center py-12">
                <div className="h-8 w-8 border-2 border-accent border-t-transparent rounded-full animate-spin" />
              </div>
            ) : applications.length === 0 ? (
              <div className="text-center py-12">
                <FileText className="mx-auto h-12 w-12 text-text-muted mb-4" />
                <p className="text-text-muted">No pending applications</p>
              </div>
            ) : (
              <div className="space-y-4">
                {applications.map((application) => (
                  <div
                    key={application.id}
                    onClick={() => setSelectedApplication(application)}
                    className="group relative overflow-hidden rounded-xl border border-border bg-white/[0.02] p-6 cursor-pointer transition-all duration-300 hover:border-accent/30 hover:bg-white/[0.04]"
                  >
                    <div className="flex items-start justify-between gap-6">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-3">
                          <div className={cn("flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-bold uppercase tracking-wider", getStatusColor(application.membershipStatus))}>
                            <Clock className="h-4 w-4" />
                            <span>{application.membershipStatus}</span>
                          </div>
                          {application.createdAt && (
                            <div className="flex items-center gap-2 text-text-muted text-sm">
                              <Calendar className="h-4 w-4" />
                              {new Date(application.createdAt?.toDate?.() || application.createdAt).toLocaleDateString()}
                            </div>
                          )}
                        </div>

                        <div className="flex items-center gap-3 mb-4">
                          <div className="h-12 w-12 rounded-full bg-accent/20 flex items-center justify-center">
                            <User className="h-6 w-6 text-accent" />
                          </div>
                          <div>
                            <h3 className="font-bold text-white text-lg">{application.displayName || application.username || 'Unknown'}</h3>
                            <div className="flex items-center gap-2 text-text-muted text-sm">
                              <Mail className="h-4 w-4" />
                              {application.email}
                            </div>
                          </div>
                        </div>

                        {application.bio && (
                          <div className="flex items-start gap-2">
                            <FileText className="h-4 w-4 text-accent mt-1 shrink-0" />
                            <p className="text-text-soft text-sm line-clamp-2">{application.bio}</p>
                          </div>
                        )}
                      </div>

                      <div className="flex items-center gap-2">
                        <span className="text-text-muted group-hover:text-white transition-colors">
                          Review →
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Members Tab */}
      {activeTab === 'members' && (
        <Card>
          <CardContent className="p-6">
            <div className="relative mb-6">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-text-muted" />
              <Input
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search members..."
                className="pl-10"
              />
            </div>

            {loading ? (
              <div className="flex items-center justify-center py-12">
                <div className="h-8 w-8 border-2 border-accent border-t-transparent rounded-full animate-spin" />
              </div>
            ) : members.length === 0 ? (
              <div className="text-center py-12">
                <Users className="mx-auto h-12 w-12 text-text-muted mb-4" />
                <p className="text-text-muted">No members found</p>
              </div>
            ) : (
              <div className="space-y-4">
                {members.filter(m => 
                  m.displayName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                  m.username?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                  m.email?.toLowerCase().includes(searchQuery.toLowerCase())
                ).map((member) => (
                  <div
                    key={member.id}
                    onClick={() => setSelectedMember(member)}
                    className="group relative overflow-hidden rounded-xl border border-border bg-white/[0.02] p-6 cursor-pointer transition-all duration-300 hover:border-accent/30 hover:bg-white/[0.04]"
                  >
                    <div className="flex items-start justify-between gap-6">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-3">
                          {member.role === 'CEO' && <Crown className="h-4 w-4 text-purple-400" />}
                          <div className={cn("flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-bold uppercase tracking-wider", getRoleColor(member.role))}>
                            <span>{member.role || 'Member'}</span>
                          </div>
                          <div className={cn("flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider", getAccountStatusColor(member.accountStatus))}>
                            <span>{member.accountStatus || 'active'}</span>
                          </div>
                        </div>

                        <div className="flex items-center gap-3 mb-4">
                          <div className="h-12 w-12 rounded-full bg-accent/20 flex items-center justify-center">
                            <User className="h-6 w-6 text-accent" />
                          </div>
                          <div>
                            <h3 className="font-bold text-white text-lg">{member.displayName || member.username || 'Unknown'}</h3>
                            <div className="flex items-center gap-2 text-text-muted text-sm">
                              <Mail className="h-4 w-4" />
                              {member.email}
                            </div>
                          </div>
                        </div>

                        {member.department && (
                          <div className="flex items-center gap-2 text-text-muted text-sm">
                            <Building2 className="h-4 w-4" />
                            {member.department}
                          </div>
                        )}
                      </div>

                      <div className="flex items-center gap-2">
                        <span className="text-text-muted group-hover:text-white transition-colors">
                          Manage →
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* History Tab */}
      {activeTab === 'history' && (
        <Card>
          <CardContent className="p-6">
            <div className="text-center py-12 text-text-muted">
              <History className="mx-auto h-12 w-12 mb-4 opacity-50" />
              <p>Membership history and audit logs will appear here.</p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Application Review Modal */}
      {selectedApplication && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setSelectedApplication(null)} />
          <div className="relative max-w-2xl w-full max-h-[90vh] overflow-y-auto bg-background border border-border rounded-3xl p-8">
            <button
              onClick={() => setSelectedApplication(null)}
              className="absolute top-4 right-4 p-2 text-text-muted hover:text-white transition-colors"
            >
              <XCircle className="h-6 w-6" />
            </button>

            <div className="mb-6">
              <div className={cn("inline-flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-bold uppercase tracking-wider mb-4", getStatusColor(selectedApplication.membershipStatus))}>
                <Clock className="h-4 w-4" />
                <span>{selectedApplication.membershipStatus}</span>
              </div>
              <h2 className="text-2xl font-bold text-white mb-2">{selectedApplication.displayName || selectedApplication.username || 'Unknown'}</h2>
              <div className="flex items-center gap-2 text-text-muted">
                <Mail className="h-4 w-4" />
                {selectedApplication.email}
              </div>
            </div>

            <div className="space-y-6">
              {selectedApplication.bio && (
                <div>
                  <h3 className="font-bold text-white mb-2">Bio</h3>
                  <p className="text-text-soft bg-white/5 rounded-lg p-4">{selectedApplication.bio}</p>
                </div>
              )}

              {selectedApplication.skills && (
                <div>
                  <h3 className="font-bold text-white mb-2">Skills</h3>
                  <p className="text-text-soft bg-white/5 rounded-lg p-4">{selectedApplication.skills}</p>
                </div>
              )}

              {selectedApplication.interests && (
                <div>
                  <h3 className="font-bold text-white mb-2">Interests</h3>
                  <p className="text-text-soft bg-white/5 rounded-lg p-4">{selectedApplication.interests}</p>
                </div>
              )}
            </div>

            {/* Action Buttons */}
            <div className="mt-8 pt-6 border-t border-border">
              <h3 className="font-bold text-white mb-4">Actions</h3>
              <textarea
                value={reviewNotes}
                onChange={(e) => setReviewNotes(e.target.value)}
                placeholder="Add review notes (optional)..."
                rows={3}
                className="w-full bg-white/5 border border-border rounded-xl px-4 py-3 text-white placeholder:text-text-muted focus:border-accent/50 focus:outline-none transition-colors resize-none mb-4"
              />
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                <Button
                  onClick={() => handleApplicationAction('approve', selectedApplication.id)}
                  disabled={submittingReview}
                  className="bg-emerald-600 hover:bg-emerald-700"
                >
                  <CheckCircle className="h-4 w-4 mr-2" />
                  Approve
                </Button>
                <Button
                  onClick={() => handleApplicationAction('reject', selectedApplication.id)}
                  disabled={submittingReview}
                  variant="destructive"
                >
                  <XCircle className="h-4 w-4 mr-2" />
                  Reject
                </Button>
                <Button
                  onClick={() => handleApplicationAction('request_info', selectedApplication.id)}
                  disabled={submittingReview}
                  variant="secondary"
                >
                  <Info className="h-4 w-4 mr-2" />
                  Request Info
                </Button>
              </div>
            </div>

            {error && (
              <div className="mt-4 p-4 bg-red-500/10 border border-red-500/30 rounded-xl text-red-400 text-sm">
                {error}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Member Management Modal */}
      {selectedMember && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setSelectedMember(null)} />
          <div className="relative max-w-2xl w-full max-h-[90vh] overflow-y-auto bg-background border border-border rounded-3xl p-8">
            <button
              onClick={() => setSelectedMember(null)}
              className="absolute top-4 right-4 p-2 text-text-muted hover:text-white transition-colors"
            >
              <XCircle className="h-6 w-6" />
            </button>

            <div className="mb-6">
              {selectedMember.role === 'CEO' && <Crown className="h-6 w-6 text-purple-400 mb-2" />}
              <div className={cn("inline-flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-bold uppercase tracking-wider mb-4", getRoleColor(selectedMember.role))}>
                <span>{selectedMember.role || 'Member'}</span>
              </div>
              <h2 className="text-2xl font-bold text-white mb-2">{selectedMember.displayName || selectedMember.username || 'Unknown'}</h2>
              <div className="flex items-center gap-2 text-text-muted">
                <Mail className="h-4 w-4" />
                {selectedMember.email}
              </div>
            </div>

            {/* Action Buttons */}
            <div className="mt-8 pt-6 border-t border-border">
              <h3 className="font-bold text-white mb-4">Member Actions</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {roleData?.role === 'CEO' && selectedMember.role !== 'CEO' && (
                  <Button
                    onClick={() => handleMemberAction('promote_co_ceo', selectedMember.id)}
                    disabled={submittingReview}
                    className="bg-purple-600 hover:bg-purple-700"
                  >
                    <Crown className="h-4 w-4 mr-2" />
                    Promote to Co-CEO
                  </Button>
                )}
                <Button
                  onClick={() => handleMemberAction('assign_leadership', selectedMember.id)}
                  disabled={submittingReview}
                  variant="secondary"
                >
                  <Award className="h-4 w-4 mr-2" />
                  Assign Leadership
                </Button>
                <Button
                  onClick={() => handleMemberAction('assign_moderator', selectedMember.id)}
                  disabled={submittingReview}
                  variant="secondary"
                >
                  <ShieldAlert className="h-4 w-4 mr-2" />
                  Assign Moderator
                </Button>
                <Button
                  onClick={() => handleMemberAction('assign_mentor', selectedMember.id)}
                  disabled={submittingReview}
                  variant="secondary"
                >
                  <Award className="h-4 w-4 mr-2" />
                  Assign Mentor
                </Button>
                <Button
                  onClick={() => handleMemberAction('suspend', selectedMember.id)}
                  disabled={submittingReview}
                  variant="secondary"
                  className="bg-amber-600 hover:bg-amber-700"
                >
                  <AlertTriangle className="h-4 w-4 mr-2" />
                  Suspend
                </Button>
                <Button
                  onClick={() => handleMemberAction('ban', selectedMember.id)}
                  disabled={submittingReview}
                  variant="destructive"
                >
                  <Ban className="h-4 w-4 mr-2" />
                  Ban
                </Button>
              </div>
            </div>

            {error && (
              <div className="mt-4 p-4 bg-red-500/10 border border-red-500/30 rounded-xl text-red-400 text-sm">
                {error}
              </div>
            )}
          </div>
        </div>
      )}
    </PageContainer>
  );
}

