                    </div>
                  </Link>
                )}
              </div>

              <h2 className="text-lg sm:text-xl font-bold text-white mb-3 sm:mb-4">My AIs</h2>
              {myAIs.length > 0 ? (
                <div className="grid gap-4 sm:gap-6 sm:grid-cols-2 lg:grid-cols-3">
